WITH emp_piv AS (SELECT p.* FROM (SELECT p.*, ROW_NUMBER() OVER (PARTITION BY p.employee_id ORDER BY p.id DESC) AS rn FROM personnel_insurance p WHERE p.insurance_type='雇主责任险' AND p.is_deleted=false) p WHERE p.rn=1),
inj_piv AS (SELECT p.* FROM (SELECT p.*, ROW_NUMBER() OVER (PARTITION BY p.employee_id ORDER BY p.id DESC) AS rn FROM personnel_insurance p WHERE p.insurance_type='工伤保险' AND p.is_deleted=false) p WHERE p.rn=1)
SELECT COUNT(*)::int AS total, COUNT(*) FILTER (WHERE inj_piv.id IS NOT NULL) AS with_inj, COUNT(*) FILTER (WHERE NOT ((emp_piv.is_current=true AND emp_piv.start_date IS NOT NULL AND emp_piv.expire_date IS NOT NULL AND emp_piv.start_date<=emp_piv.expire_date AND emp_piv.start_date<=(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Shanghai')::date AND emp_piv.expire_date>=(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Shanghai')::date AND COALESCE(emp_piv.coverage_amount,0)>=800000) OR (emp_piv.is_current=true AND emp_piv.start_date IS NOT NULL AND emp_piv.expire_date IS NOT NULL AND emp_piv.start_date<=emp_piv.expire_date AND emp_piv.start_date<=(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Shanghai')::date AND emp_piv.expire_date>=(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Shanghai')::date AND COALESCE(emp_piv.coverage_amount,0)>=100000 AND inj_piv.id IS NOT NULL) OR (inj_piv.id IS NOT NULL AND NOT (emp_piv.is_current=true AND emp_piv.start_date IS NOT NULL AND emp_piv.expire_date IS NOT NULL AND emp_piv.start_date<=emp_piv.expire_date AND emp_piv.start_date<=(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Shanghai')::date AND emp_piv.expire_date>=(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Shanghai')::date)))) AS noncompliant
FROM v_employee_current ev LEFT JOIN emp_piv ON emp_piv.employee_id=ev.employee_id LEFT JOIN inj_piv ON inj_piv.employee_id=ev.employee_id WHERE ev.employee_deleted=false;
